void MapTransferLoadScreen::setCurrentFilename(AsciiString filename)
{
	if (m_fileNameText)
	{
		UnicodeString text;
		text.translate(TheGameState->getMapLeafName(filename));
		text.format(TheGameText->fetchPtr("MapTransfer:CurrentFile", 0), text.str());
		GadgetStaticTextSetText(m_fileNameText, text);
	}
}

